import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Web / Node","description":"KiriVers ships installable objects. Refreshing a page is not a site upgrade. Browser apps cannot use the TypeScript SDK.","frontmatter":{"title":"Web / Node","description":"KiriVers ships installable objects. Refreshing a page is not a site upgrade. Browser apps cannot use the TypeScript SDK."},"headers":[],"relativePath":"en/guide/scenarios/web-node.md","filePath":"en/guide/scenarios/web-node.md","lastUpdated":1790057721000}`),a={name:`en/guide/scenarios/web-node.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="web-node" tabindex="-1">Web / Node <a class="header-anchor" href="#web-node" aria-label="Permalink to “Web / Node”">​</a></h1><p>KiriVers distributes <strong>installable objects</strong> (SHA-256 files). Reloading a web page is not a site-upgrade channel.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to “When to use it”">​</a></h2><ul><li>Site static assets / SPA builds: your own CDN / pipeline, not KiriVers check.</li><li>A <strong>Node server process</strong> in the same product (daemon, CLI): native JSON <strong>POST</strong> check.</li><li>A desktop shell (Electron) wrapping a web UI: the installer uses an <a href="./electron">Electron</a> listing or a homegrown client inside the shell.</li></ul><p>The official TypeScript SDK has <strong>no</strong> browser export and cannot call check in a web page.</p><h2 id="where-to-configure" tabindex="-1">Where to configure <a class="header-anchor" href="#where-to-configure" aria-label="Permalink to “Where to configure”">​</a></h2><p>Node processes: project <strong>Settings</strong> rate limits / tokens, plus <a href="/en/guide/features/check">Update check</a>. Electron shells: <strong>Settings → Store listings</strong> → <strong>New listing</strong>.</p><h2 id="client-updater-duties" tabindex="-1">Client / updater duties <a class="header-anchor" href="#client-updater-duties" aria-label="Permalink to “Client / updater duties”">​</a></h2><table tabindex="0"><thead><tr><th>Shape</th><th>Approach</th></tr></thead><tbody><tr><td>In-browser web app</td><td>Do not use the TypeScript SDK. Ship site assets with your own CDN / build</td></tr><tr><td>Node server process</td><td><strong>POST</strong> check as in <a href="./server-cli">Servers and CLI</a></td></tr><tr><td>Electron shell</td><td><a href="./electron">Electron</a> store listing, or a homegrown native JSON client inside the shell</td></tr></tbody></table><h2 id="failures" tabindex="-1">Failures <a class="header-anchor" href="#failures" aria-label="Permalink to “Failures”">​</a></h2><p>Importing the official SDK in a browser fails (no browser build). Uploading site HTML as an “installer” does not make a page reload run check. Node processes must <strong>POST</strong>; GET check is 404.</p><p>Related: <a href="/en/guide/features/check">Update check</a>, <a href="/en/api/sdk/">SDK</a>.</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};